// src/assistant/DraftCard.jsx
// Handles draft proposals generated by the assistant (actions, summary)
import React, { useState } from 'react';
import { Check, X, Edit3, ArrowRight, AlertCircle } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';
import { canAcceptAssistantDraft } from '../auth/permissions';
import { createAction, updateMinutes } from '../services/api';
import { useToast } from '../components/Toast';

export default function DraftCard({ draft, onDismiss }) {
  const { currentUser } = useAuth();
  const { showToast } = useToast();
  const [accepted, setAccepted] = useState(false);
  const [editing, setEditing] = useState(false);
  const [customText, setCustomText] = useState(
    draft.type === 'summary' ? draft.text : ''
  );

  const permissionCheck = canAcceptAssistantDraft(currentUser, draft.type);

  const handleAccept = async () => {
    if (!permissionCheck.allowed) return;

    try {
      if (draft.type === 'actions' && draft.items) {
        for (const item of draft.items) {
          await createAction({
            title: item.title,
            ownerName: item.suggestedOwner || currentUser.name,
            priority: item.priority || 'Medium',
            dueDate: item.dueDate || '2026-11-20',
            description: 'Created from AI assistant recommendation.',
          });
        }
        showToast('Accepted and added action items to workspace!', 'success');
      } else if (draft.type === 'summary') {
        showToast('Accepted draft notes into session summary!', 'success');
      }
      setAccepted(true);
    } catch (err) {
      showToast(`Error accepting draft: ${err.message}`, 'error');
    }
  };

  if (accepted) {
    return (
      <div className="p-3 rounded-card bg-success-bg border border-success-border text-xs text-text-primary flex items-center justify-between">
        <div className="flex items-center gap-2 text-success font-semibold">
          <Check className="w-4 h-4" />
          <span>Draft accepted and recorded.</span>
        </div>
        <a
          href="/actions"
          className="inline-flex items-center gap-1 font-semibold text-text-primary hover:underline text-[11px]"
        >
          <span>View records</span>
          <ArrowRight className="w-3 h-3" />
        </a>
      </div>
    );
  }

  return (
    <div className="p-3.5 rounded-card bg-surface border border-accent/60 shadow-sm space-y-2.5 animate-fade-in my-2">
      {/* Draft Header */}
      <div className="flex items-center justify-between">
        <span className="px-2 py-0.5 rounded-full bg-accent text-accent-text text-[10px] font-mono font-bold uppercase tracking-wider">
          Draft Proposal
        </span>
        <span className="text-[11px] text-text-secondary font-mono">
          Requires confirmation
        </span>
      </div>

      {/* Content */}
      {draft.type === 'summary' ? (
        editing ? (
          <textarea
            value={customText}
            onChange={(e) => setCustomText(e.target.value)}
            className="w-full text-xs p-2 rounded-input bg-surface-muted border border-border focus:outline-none focus:border-accent"
            rows={3}
          />
        ) : (
          <p className="text-xs text-text-primary italic leading-relaxed">
            "{customText || draft.text}"
          </p>
        )
      ) : draft.type === 'actions' && draft.items ? (
        <div className="space-y-2">
          {draft.items.map((item, idx) => (
            <div
              key={idx}
              className="p-2 rounded-btn bg-surface-muted/60 border border-border text-xs space-y-1"
            >
              <div className="font-medium text-text-primary">{item.title}</div>
              <div className="flex items-center justify-between text-[11px] text-text-secondary font-mono">
                <span>
                  Suggested owner: <strong>{item.suggestedOwner}</strong>
                </span>
                <span className="px-1.5 py-0.2 rounded bg-surface border border-border">
                  {item.priority}
                </span>
              </div>
            </div>
          ))}
          <p className="text-[11px] text-text-secondary italic">
            Confirm before assigning to team members.
          </p>
        </div>
      ) : null}

      {/* Permission Restriction Notice if Participant tries to accept minutes/approval */}
      {!permissionCheck.allowed && (
        <div className="flex items-start gap-1.5 text-[11px] text-error font-medium p-2 rounded-btn bg-error-bg">
          <AlertCircle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
          <span>{permissionCheck.reason}</span>
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center justify-end gap-2 pt-1 border-t border-border">
        {draft.type === 'summary' && !editing && (
          <button
            onClick={() => setEditing(true)}
            className="px-2.5 py-1 rounded-btn text-xs text-text-secondary hover:text-text-primary hover:bg-surface-muted transition-colors flex items-center gap-1"
          >
            <Edit3 className="w-3 h-3" />
            <span>Edit</span>
          </button>
        )}
        <button
          onClick={onDismiss}
          className="px-2.5 py-1 rounded-btn text-xs text-text-secondary hover:text-text-primary hover:bg-surface-muted transition-colors flex items-center gap-1"
        >
          <X className="w-3 h-3" />
          <span>Reject</span>
        </button>
        <button
          disabled={!permissionCheck.allowed}
          onClick={handleAccept}
          className="px-3 py-1 rounded-btn text-xs font-semibold bg-accent text-accent-text hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-xs flex items-center gap-1 btn-press"
        >
          <Check className="w-3.5 h-3.5" />
          <span>Accept</span>
        </button>
      </div>
    </div>
  );
}

